<?php
require dirname(__DIR__) . '/includes/bootstrap.php'; $user=require_role('owner'); $title='Your listings';
$where='d.owner_id=? AND d.deleted_at IS NULL'; $params=[$user['id']];
if (get('q')!=='') { $where.=' AND d.name LIKE ?'; $params[]='%' . get('q') . '%'; }
if (in_array(get('status'),['pending','approved','rejected'],true)) { $where.=' AND d.status=?'; $params[]=get('status'); }
$total=(int)scalar('SELECT COUNT(*) FROM dormitories d WHERE ' . $where,$params);
$listings=rows(listing_select() . ' WHERE ' . $where . ' ORDER BY d.id DESC LIMIT 10 OFFSET ' . ((page_number()-1)*10),$params);
require ROOT . '/includes/dashboard-start.php';
?>
<p>Keep your rooms, prices, and availability current.</p><a class="btn btn-primary mb-4" href="<?= url('owner/add-listing.php') ?>">Add a listing</a><form class="inline-filter" method="get"><?php field('Search listings','q',get('q'),'search'); select_field('Review status','status',[['id'=>'pending','name'=>'Pending'],['id'=>'approved','name'=>'Approved'],['id'=>'rejected','name'=>'Rejected']],get('status')); ?><button class="btn btn-primary">Filter</button></form><div class="table-responsive panel table-panel"><table class="table"><thead><tr><th>Dormitory</th><th>Monthly rent</th><th>Slots</th><th>Review status</th><th>Visibility</th><th>Actions</th></tr></thead><tbody><?php foreach ($listings as $d): ?><tr><td><strong><?= e($d['name']) ?></strong><?php if ($d['rejection_reason']): ?><small class="d-block text-danger"><?= e($d['rejection_reason']) ?></small><?php endif; ?></td><td><?= money($d['monthly_rent']) ?></td><td><?= $d['available_slots'] ?>/<?= $d['capacity'] ?></td><td><span class="status-badge <?= e($d['status']) ?>"><?= e($d['status']) ?></span></td><td><?= $d['is_active'] ? 'Active' : 'Inactive' ?></td><td><a href="<?= url('owner/edit-listing.php?id=' . $d['id']) ?>">Edit</a> · <a href="<?= url('dorm-details.php?id=' . $d['id']) ?>">Preview</a></td></tr><?php endforeach; ?><?php if (!$listings): ?><tr><td colspan="6">No listings found. Add your first place to get started.</td></tr><?php endif; ?></tbody></table></div><?php paginate($total,10); require ROOT . '/includes/dashboard-end.php'; ?>
